{"cards": [{"node_code": "N_e82900e62c903634", "definition": "针对黄土地区特有的湿陷性、崩解性及易受水蚀等地质特性，在公路建设中采用的路基处理、边坡防护、排水设计及特殊施工技术与措施。", "boundary": "本节点聚焦于黄土环境下的筑路技术。边界在于区分“黄土地区”与“喀斯特地区”（前者侧重湿陷与土体稳定性，后者侧重岩溶空洞与地基承载力）；区分“黄土地区”与“沙漠地区”（前者侧重水敏性，后者侧重风沙与干旱）。若内容仅涉及黄土力学性质研究而不涉及工程应用，需视具体学科归属，本节点侧重工程措施。", "includes": ["黄土湿陷性路基处理与加固技术", "黄土边坡稳定性分析与防护工程", "黄土地区排水系统设计与水蚀防治措施"], "excludes": ["喀斯特岩溶地区的筑路技术", "沙漠与干旱地区的风沙防治技术", "常规非黄土地区的通用路基施工技术"], "sibling_distinctions": [{"other_code": "N_931fcc616822cb96", "rule": "区分依据为地质成因与主要危害：黄土地区主要应对湿陷性、崩解性及水蚀；喀斯特地区主要应对岩溶空洞、地基不均匀沉降及地下水涌出。"}, {"other_code": "N_709c77de5e0dd4c1", "rule": "区分依据为气候与介质：黄土地区侧重土体水敏性与侵蚀；沙漠地区侧重风沙活动、干旱缺水及路基防沙。"}], "cross_boundary_rule": "若内容涉及黄土地区桥梁基础处理，侧重路基与边坡归本节点，侧重桥梁桩基在黄土中的受力可关联桥涵工程，但本节点优先收录路基相关技术。"}, {"node_code": "N_6f1c6f2c2fc62edc", "definition": "针对盐渍土地区特有的盐胀、溶陷、冻胀及腐蚀性等环境因素，在公路建设中采用的路基改良、材料选择、结构设计与防护措施。", "boundary": "本节点聚焦于盐渍土环境下的筑路技术。边界在于区分“盐渍地区”与“冰冻地区”（前者侧重盐分结晶与溶解引起的体积变化及腐蚀，后者侧重低温冻融循环）；区分“盐渍地区”与“泥沼地区”（前者侧重土体盐分特性，后者侧重高含水量与低承载力）。若内容仅涉及盐渍土材料性能，需结合工程应用归入本节点。", "includes": ["盐渍土路基的盐胀与溶陷防治技术", "盐渍土地区的道路材料改良与防腐处理", "盐渍土地区路基排水与蒸发控制措施"], "excludes": ["冰冻与严寒地区的冻融循环防治技术", "泥沼地区的高含水量地基处理技术", "常规非盐渍土地区的通用路面施工技术"], "sibling_distinctions": [{"other_code": "N_537dd445e590b1ba", "rule": "区分依据为致害机理：盐渍地区主要应对盐分结晶/溶解引起的体积变化及化学腐蚀；冰冻地区主要应对水分冻结/融化引起的体积变化及冻融循环。"}, {"other_code": "N_19e59c9b7b4a2ecf", "rule": "区分依据为土体状态：盐渍地区侧重土体含盐量及其物理化学性质变化；泥沼地区侧重土体高含水量、低强度及流变特性。"}], "cross_boundary_rule": "若内容涉及盐渍土地区桥梁基础防腐，侧重路基与路面归本节点，侧重桥梁结构防腐可关联桥涵工程，但本节点优先收录路基相关技术。"}, {"node_code": "N_d61b4f4a790a0063", "definition": "针对多雨与炎热地区特有的高温、强降水、湿热气候等环境因素，在公路建设中采用的路面抗滑、排水、耐热及防病害设计与施工技术。", "boundary": "本节点聚焦于湿热气候环境下的筑路技术。边界在于区分“多雨炎热”与“冰冻严寒”（前者侧重高温、雨水冲刷与湿热老化，后者侧重低温冻融）；区分“多雨炎热”与“沙漠干旱”（前者侧重水损害与高温，后者侧重风沙与温差）。若内容仅涉及通用路面材料，需结合湿热环境下的性能表现归入本节点。", "includes": ["多雨地区的路面排水设计与水损害防治", "炎热地区的路面耐热、抗车辙与抗滑技术", "湿热气候下的路基稳定与防病害措施"], "excludes": ["冰冻与严寒地区的冻融防治技术", "沙漠与干旱地区的风沙防治技术", "常规非湿热地区的通用道路设计标准"], "sibling_distinctions": [{"other_code": "N_537dd445e590b1ba", "rule": "区分依据为温度与水分状态：多雨炎热地区侧重高温、多水及湿热老化；冰冻严寒地区侧重低温、冻融循环及冰雪覆盖。"}, {"other_code": "N_709c77de5e0dd4c1", "rule": "区分依据为水分与风沙：多雨炎热地区侧重降水冲刷与高温；沙漠干旱地区侧重缺水、风沙活动及大温差。"}], "cross_boundary_rule": "若内容涉及多雨炎热地区桥梁排水，侧重路面与路基排水归本节点，侧重桥梁结构排水可关联桥涵工程，但本节点优先收录路面与路基相关技术。"}]}
